import collections,json,statistics
from common import *
from memory import ARMS
def n(v):return f'{v:,}'.replace(',',' ')
def pp(v):return f'{100*v:+.2f}'.replace('.',',')
def main():
    lines=['# Память для следующей исполняемой правки','',
    '**Окончательные результаты авторских тестов получены с исправленной областью видимости тестового окружения.** Первоначальная оболочка скрывала вспомогательные функции encode_shift и encode_cyclic в двух задачах. Для всех 777 исходов повторно оценены уже зафиксированные ответы. Все 111 эталонов проходят авторские тесты, все 111 неисправных исходников их проваливают. Первоначальные оценки сохранены для аудита. Подробности исправления и проверки неизменности вспомогательных функций находятся в NAMESPACE_CORRECTION.md и helper_integrity.json.', '',
    'Подлинные исправления генерировала локальная Qwen3.8-27B, файл GGUF UD-Q4_K_M, RTX 3090. После одного физического чтения исходного файла модель указывала подозрительную строку. Инструмент действительно читал соседние пять строк и запускал опубликованные примеры. Введённая исследователем граница обнуляла историю разговора. Каждый новый reader получал описание задачи и запись одного из пяти форматов. Можно было один раз запросить целиком текущий файл и затем вернуть одну замену диапазона строк. Применённые исправления оценены полными авторскими тестами HumanEvalPack Python.',
    '', 'Выборка зафиксирована до генерации. Из 164 задач 111 удовлетворили условиям по размеру, области и разрешённому синтаксису. Первые 48 по фиксированному хешу образовали основную выборку. Проверка на всех оставшихся 63 зарегистрирована до открытия результатов первых 48. Обе части происходят из одного публичного набора. Декодирование детерминированное, одна траектория каждого условия.',
    '', 'Новый способ начинал с полной наблюдавшейся инструкции Python, содержащей указанную моделью строку. Затем добавлялись управляющие заголовки и ближайшие строки, пока представление помещалось в 80 токенов. Главный контроль компактно восстанавливал один непрерывный участок вокруг той же строки. У всех ограниченных способов верхняя граница идентична, фактическое заполнение различается. Контроль последних наблюдений включал текст последнего чтения и результат примеров. При пустой записи можно было вновь прочитать файл. Полный исходник задавал ориентир при снятом ограничении объёма памяти.',
    '', '| Выборка | Формат | Прошли тесты | Сразу после возобновления | Повторные чтения | Входные токены | Выходные токены |',
    '|---|---|---:|---:|---:|---:|---:|']
    names={'none':'Пустая запись','recent':'Последние наблюдения','center':'Непрерывный участок вокруг фокуса','bundle':'Инструкция и заголовки','full':'Весь исходник','gate':'Условный отбор по видимости заголовка'}
    allsummary={};cost=collections.Counter()
    for s in ('','transfer'):
        d=read((ROOT/s/'corrected_results.json').relative_to(ROOT));rs=d['all']['rows'];k='Основная, 48' if not s else 'Перенос, 63'
        for a in (*ARMS,'gate'):
            row=rs[a]
            lines.append(f"| {k} | {names[a]} | {row['solves']} | {row['first_solves']} | {row['rereads']} | {n(row['input_tokens'])} | {n(row['output_tokens'])} |")
        by=collections.Counter()
        for f in (ROOT/s/'calls').glob('*.gz'):
            rec=read(f.relative_to(ROOT));usage=rec['response']['usage']
            for key in ('prompt_tokens','completion_tokens'):by[key]+=usage[key]
            by['calls']+=1
        cost.update(by)
        pref=[read(p.relative_to(ROOT)) for p in sorted((ROOT/s/'prefix').glob('*.json'))]
        di=collections.Counter()
        for g in pref:
            di['same_bundle_center']+=g['notes']['bundle']==g['notes']['center']
            di['same_center_full']+=g['notes']['center']==g['notes']['full']
            di['valid_focus']+=g['localization_valid']
            di['public_'+g['example_run']['status']]+=1
        allsummary[s or 'primary']={'actual_calls':dict(by),'prefix_diagnostics':dict(di)}
    for s in ('','transfer'):
        d=read((ROOT/s/'corrected_results.json').relative_to(ROOT));k='Основная выборка' if not s else 'Проверка на остальных задачах'
        p=d['all']['paired']['bundle-center-hit'];f=d['all']['paired']['bundle-center-first_hit']
        rs=d['all']['rows'];diag=allsummary[s or 'primary']['prefix_diagnostics']
        lines+=['','## '+k,'',
        f"Средняя парная разность «инструкция и заголовки» минус «непрерывный участок» по прохождению авторских тестов равна {pp(p['mean_delta'])} п.п. Интервал 95% по задачам [{pp(p['ci95'][0])}, {pp(p['ci95'][1])}] п.п., выигрышей {p['wins']}, потерь {p['losses']}, равных исходов {p['ties']}. Точный двусторонний p Мак-Немара {p['exact_p']:.4f}. На непосредственно выполненной правке без повторного чтения разность {pp(f['mean_delta'])} п.п., интервал [{pp(f['ci95'][0])}, {pp(f['ci95'][1])}] п.п.",
        '',f"На {diag['same_bundle_center']} задачах из {len(d['task_ids'])} оба формата послали идентичную память. У {diag['same_center_full']} непрерывный участок вмещал весь исходник. Условный выбор по видимости заголовка включал новый способ в {d['gate_used']} случаях. Это офлайн-сочетание неизменённых реально выполненных ветвей.",
        '',f"Оригинальное неисправное решение прошло {rs['buggy']['solves']} проверок, эталонное решение прошло {rs['canonical']['solves']}. Срез с проходящим эталоном и падающим исходником содержит {d['n_valid']} задач. Пообъектные статусы, включая ограничения среды, указаны в corrected_scores.json.gz."]
    lines+=['','## Повторная оценка тех же правок на HumanEval+','',
      'Дополнительный исход и версия тестов зафиксированы до просмотра основных результатов. Запущен полный опубликованный набор проверок каждой соответствующей задачи HumanEval+ OriginFmt v0.1.10 в изолированной среде с отдельным лимитом в 5 секунд. Новой генерации решений не было. Для 777 оценок потребовалось 407 уникальных запусков по паре «задача, SHA исправленного кода». [Выпуск HumanEval+ v0.1.10](https://github.com/evalplus/humanevalplus_release/releases/tag/v0.1.10).','',
      '| Выборка | Пусто | Последние | Участок | Инструкция | Весь файл | Эталон | Исходник |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for s in ('','transfer'):
        ds=read((ROOT/s/'evalplus_results.json').relative_to(ROOT))
        for name,label in [('primary','Все'),('sensitivity','Эталон проходит, исходник падает')]:
            entry=ds[name];cohort='первая' if not s else 'перенос'
            vals=[str(entry['arms'][a]['plus_solves']) for a in (*ARMS,'canonical','buggy')]
            lines.append('| '+f"{label}, {cohort}, {entry['n']}"+' | '+' | '.join(vals)+' |')
    lines+=['','На переносе оба формата памяти прошли 47 из 63 расширенных наборов. Пять выигрышей и пять потерь дают нулевую среднюю разность и парный бутстрэп-интервал [−9,52, +9,52] п.п. В срезе с работоспособным эталоном и падающим исходником получено 42 из 52 у обоих. Первоначальные эталоны HumanEvalPack на расширенных тестах дали 12 ошибок проверок и 6 превышений лимита времени в двух выборках вместе. Исходные программы получили ноль успешных результатов. На уровне функции дополнительные управляющие заголовки иногда меняют немедленное решение и потребность в повторном чтении. Устойчивого выигрыша в итоговой корректности здесь не видно.',
      '', 'В evalplus_rows.json.gz поле base_hit сохранено относительно первоначальной версии тестовой оболочки. Окончательное сравнение делается по id и arm с полем hit в corrected_scores.json.gz.']
    lines+=['','## Вычисления и границы сравнения','',
        f"С учётом общего вызова для выбора места чтения выполнено {cost['calls']} различных нативных запросов. Учтено {n(cost['prompt_tokens'])} входных и {n(cost['completion_tokens'])} выходных токенов. Табличные оценки по политикам считают логическую цену каждой независимо развёрнутой ветви. Идентичные запросы в эксперименте получали один завершённый ответ.",
        '','Пары сравнивались по полным авторским тестам. Функции исполнялись в отдельных процессах с ограничением времени и памяти. Использован ограниченный Python AST. Список разрешённых операций зафиксирован до просмотра ответов. Отклонение синтаксиса среды, неправильный JSON, пустая замена и неверные тестовые исходы разнесены в данных. Ограничение на одну замену и искусственная пауза отличаются от исходного протокола свободной генерации HumanEvalFix. Потенциальное знакомство модели с публичными задачами неизвестно. Проекты SWE и более длинные сессии требуют отдельного исполнимого сравнения.',
        '', '## Проверка','',
        'verify.py проверяет манифесты, точное соответствие запросов и ответов, цену повторных чтений, SHA физически отредактированных файлов и парные статистики. Опции --execute --tokens повторно исполняют тесты и пересчитывают токенный бюджет. Доступ к сети и новая генерация не требуются. Native server logs, аппаратные сведения, модель и хеши бинарных файлов лежат в runtime. Сверка с оригинальной постановкой и ссылки находятся в HARNESS.md.']
    lines+=['','## Чувствительность HumanEval+ к лимиту исполнения','',
      'При независимом повторении физического теста prime_fib одна и та же программа получила pass после прежнего timeout. Оценка с пятисекундным лимитом зависит от нагрузки машины. Все опубликованные выше первичные знаменатели и метки сохранены. Дополнительно исключены задачи, на которых хотя бы один метод или контроль получил timeout в первоначальном расширенном тесте. На первой выборке это даёт 40 против 40 из 45. На переносе получено 45 против 43 из 56, 5 выигрышей и 3 потери, разность +3,57 п.п., интервал [−7,14, +14,29], p=0,727. Критерий выбирает задачи по наблюдавшемуся исходу и служит описательной проверкой. Все пообъектные повторы хранятся в evalplus_replay.json.gz и transfer/evalplus_replay.json.gz, итоги — в evalplus_timing_audit.json.',
      '', 'Команда python -B verify_final.py проверяет окончательные метки и статистики по двум наборам тестов. Флаг --execute повторяет обе серии физических тестов и сообщает каждое расхождение из-за таймаута, а --tokens пересчитывает бюджеты. Описание зависимостей находится в REPRODUCE.md.']
    timing=read('evalplus_timing_audit.json')
    subst=timing['repeat_results']['transfer']['counts']
    lines.insert(-2,f"В полном повторном исполнении источники и статусы совпали для {timing['distinct_physical_files_by_task']-len(timing['timeout_disagreements'])} из {timing['distinct_physical_files_by_task']} уникальных программ. Для prime_fib в переносе изменился исход только у пустой памяти: 50 из 63 в первой серии и {subst['none']} из 63 при повторе. У инструкции с заголовками и непрерывного участка осталось по {subst['bundle']} из 63.")
    lines.insert(-3,'')
    (ROOT/'summary_ru.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
    save('derived.json',{'cohorts':allsummary,'actual':dict(cost)})
if __name__=='__main__':main()
